// Purple Bitcoin coin icon, base64-inlined so the sticker SVG downloads
// as a single self-contained file. A merchant can email this SVG to a
// print shop or drop it into Canva without the icon dropping out — no
// external <image href="/icon.png"> dependency, no taint-canvas blowup
// in the SVG -> PNG export path inside `sticker-client.tsx`.
//
// Source file is `public/purple-club-icon.png` (a copy of Purple Club's
// `icon-512.png`). To re-embed after the source changes, run from the
// `Purple Club` directory:
//
//   node -e "console.log(require('fs').readFileSync('public/purple-club-icon.png').toString('base64'))"
//
// and paste over the string below.

export const PURPLE_BITCOIN_ICON_DATA_URI =
  "data:image/png;base64,";